async function hmacSha1Base64(keyText:string,value:string){const enc=new TextEncoder();const key=await crypto.subtle.importKey("raw",enc.encode(keyText),{name:"HMAC",hash:"SHA-1"},false,["sign"]);const sig=await crypto.subtle.sign("HMAC",key,enc.encode(value));let b="";for(const n of new Uint8Array(sig))b+=String.fromCharCode(n);return btoa(b);}
async function verifySignature(req:Request,p:URLSearchParams){if(!authToken)return false;const got=req.headers.get("X-Twilio-Signature")||"";if(!got)return false;const keys=Array.from(new Set(Array.from(p.keys()))).sort();let payload=canonicalWebhookUrl||req.url;for(const k of keys)for(const v of p.getAll(k))payload+=`${k}${v}`;const expected=await hmacSha1Base64(authToken,payload);if(got.length!==expected.length)return false;let diff=0;for(let i=0;i<got.length;i++)diff|=got.charCodeAt(i)^expected.charCodeAt(i);return diff===0;}
async function verifyRest(p:URLSearchParams){try{const sid=p.get("MessageSid")||p.get("SmsSid")||"";if(!sid||p.get("AccountSid")!==accountSid)return false;const r=await fetch(`https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages/${encodeURIComponent(sid)}.json`,{headers:{Authorization:basic()}});const d=await r.json();if(!r.ok||d.sid!==sid||d.account_sid!==accountSid)return false;if(p.get("From")&&d.from!==p.get("From"))return false;if(p.get("To")&&d.to!==p.get("To"))return false;if(p.get("Body")!==null&&String(d.body||"")!==String(p.get("Body")||""))return false;return true;}catch{return false;}}
async function twilioSend(form:URLSearchParams){if(!accountSid||!authToken||!fromNumber)throw new Error("Twilio WhatsApp is not configured");if(statusCallback)form.set("StatusCallback",statusCallback);const r=await fetch(`https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`,{method:"POST",headers:{Authorization:basic(),"Content-Type":"application/x-www-form-urlencoded"},body:form});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d?.message||`Twilio HTTP ${r.status}`);return d;}
async function activity(s:any,threadId:string,type:string,metadata:any={}){await s.from("adminos_whatsapp_activity").insert({thread_id:threadId,actor_id:null,event_type:type,metadata});}
async function persistSent(s:any,thread:any,contactId:string|null,to:string,sent:any,body:string|null,metadata:any={},touch=true){const now=new Date().toISOString();const row=await s.from("adminos_whatsapp_messages").upsert({thread_id:thread.id,contact_id:contactId,twilio_message_sid:sent.sid,direction:"outbound",from_address:wa(fromNumber),to_address:wa(to),body_text:body,message_kind:"service",status:sent.status==="queued"?"queued":"sent",risk_level:"green",sent_at:now,metadata:{source:"dimpho_whatsapp",author_type:"ai",persona:"Dimpho",...metadata}},{onConflict:"twilio_message_sid"}).select("id").maybeSingle();if(touch)await s.from("adminos_whatsapp_threads").update({last_message_at:now,last_outbound_at:now,status:"waiting",updated_at:now}).eq("id",thread.id);else await s.from("adminos_whatsapp_threads").update({last_message_at:now,last_outbound_at:now,updated_at:now}).eq("id",thread.id);await activity(s,thread.id,"dimpho.sent",{message_id:row.data?.id||null,twilio_message_sid:sent.sid,...metadata});return row.data;}
async function sendText(s:any,thread:any,contactId:string|null,to:string,body:string,metadata:any={},touch=true){const clipped=body.trim().slice(0,3500);const sent=await twilioSend(new URLSearchParams({From:wa(fromNumber),To:wa(to),Body:clipped}));await persistSent(s,thread,contactId,to,sent,clipped,metadata,touch);return sent;}
async function sendMedia(s:any,thread:any,contactId:string|null,to:string,body:string,url:string,metadata:any={}){const sent=await twilioSend(new URLSearchParams({From:wa(fromNumber),To:wa(to),Body:body.slice(0,3000),MediaUrl:url}));await persistSent(s,thread,contactId,to,sent,body,{...metadata,rich_media:true});return sent;}
async function sendRich(s:any,thread:any,contactId:string|null,to:string,key:string,vars:Record<string,string>={}){const row=(await s.from("adminos_whatsapp_rich_content").select("*").eq("content_key",key).maybeSingle()).data;if(!row?.content_sid)throw new Error(`Rich WhatsApp content ${key} is not ready`);const form=new URLSearchParams({From:wa(fromNumber),To:wa(to),ContentSid:row.content_sid});if(Object.keys(vars).length)form.set("ContentVariables",JSON.stringify(vars));const sent=await twilioSend(form);await persistSent(s,thread,contactId,to,sent,String(row.config?.body||row.display_name),{content_key:key,content_sid:row.content_sid});await s.from("adminos_whatsapp_threads").update({last_menu_key:key,last_menu_at:new Date().toISOString()}).eq("id",thread.id);thread.last_menu_key=key;thread.last_menu_at=new Date().toISOString();return sent;}
async function sendMenuIfUseful(s:any,thread:any,contactId:string|null,to:string,key:string,vars:Record<string,string>={},force=false){const recent=thread.last_menu_key===key&&thread.last_menu_at&&Date.now()-new Date(thread.last_menu_at).getTime()<10*60*1000;if(recent&&!force)return false;await sendRich(s,thread,contactId,to,key,vars);return true;}

async function identity(s:any,contactId:string|null,from:string){let contact:any=contactId?(await s.from("adminos_contacts").select("*").eq("id",contactId).maybeSingle()).data:null;let profile:any=null;if(contact?.profile_user_id)profile=(await s.from("profiles").select("id,full_name,email,phone,phone_number,student_number,campus,course,profile_picture_url").eq("id",contact.profile_user_id).maybeSingle()).data||null;if(!profile){const intl=e164(from),local=intl.startsWith("+27")?`0${intl.slice(3)}`:intl;profile=(await s.from("profiles").select("id,full_name,email,phone,phone_number,student_number,campus,course,profile_picture_url").or(`phone.eq.${intl},phone_number.eq.${intl},phone.eq.${local},phone_number.eq.${local}`).limit(1).maybeSingle()).data||null;if(profile&&contactId&&!contact?.profile_user_id){await s.from("adminos_contacts").update({profile_user_id:profile.id,full_name:contact?.full_name||profile.full_name,email:contact?.email||profile.email,student_number:contact?.student_number||profile.student_number,campus:contact?.campus||profile.campus,updated_at:new Date().toISOString()}).eq("id",contactId);contact={...(contact||{}),profile_user_id:profile.id};}}return{contact,profile};}
async function state(s:any,thread:any,patch:any){const next={...(thread.conversation_state||{}),...patch};await s.from("adminos_whatsapp_threads").update({conversation_state:next,intent:patch.intent||thread.intent||null,updated_at:new Date().toISOString()}).eq("id",thread.id);thread.conversation_state=next;if(patch.intent)thread.intent=patch.intent;return next;}
async function touchConversion(s:any,thread:any,contactId:string|null,profile:any,intent:string,stage:string,patch:any={}){const payload={...patch,academic_year:patch.academic_year??patch.year,tenant_type:patch.tenant_type??patch.tenant};const r=await s.rpc("adminos_touch_whatsapp_conversion",{p_thread_id:thread.id,p_contact_id:contactId,p_user_id:profile?.id||null,p_intent:intent,p_stage:stage,p_patch:payload});if(r.error&&String(r.error.message||"").toLowerCase().includes("does not exist")===false)console.error("conversion touch",r.error.message);return r.data||null;}
async function setLanguage(s:any,thread:any,contactId:string|null,code:string,source="selected",confidence=1){if(!LANGS.has(code))return;thread.language_code=code;if(contactId){const r=await s.rpc("adminos_set_contact_language",{p_contact_id:contactId,p_language_code:code,p_source:source,p_confidence:confidence});if(r.error)await s.from("adminos_whatsapp_threads").update({language_code:code,updated_at:new Date().toISOString()}).eq("id",thread.id);}else await s.from("adminos_whatsapp_threads").update({language_code:code,updated_at:new Date().toISOString()}).eq("id",thread.id);}
async function phrase(s:any,key:string,code:string){return (await s.from("adminos_i18n_phrases").select("phrase_text").eq("phrase_key",key).eq("language_code",code).maybeSingle()).data?.phrase_text||(await s.from("adminos_i18n_phrases").select("phrase_text").eq("phrase_key",key).eq("language_code","en").maybeSingle()).data?.phrase_text||"Thank you.";}
async function detectLanguage(s:any,thread:any,contactId:string|null,body:string){if(!body.trim()||body.includes(":"))return thread.language_code||"en";const r=await s.rpc("adminos_detect_language",{p_text:body});const code=LANGS.has(String(r.data||""))?String(r.data):"en";if(code!=="en"&&code!==thread.language_code)await setLanguage(s,thread,contactId,code,"detected",0.85);return code!=="en"?code:(thread.language_code||"en");}
function selectionFrom(p:URLSearchParams,body:string){const direct=txt(p.get("ButtonPayload"));if(direct)return direct;const raw=txt(p.get("InteractiveData"));if(raw){try{const d=JSON.parse(raw);return txt(d?.id||d?.payload||d?.button_payload||d?.selected_id)||body;}catch{}}return body;}
const greeting=(v:string)=>/^(hi|hii+|hello|hey|good\s*(morning|afternoon|evening)|howzit|dumelang|dumela|sawubona|molo|hallo)[!.\s]*$/i.test(v.trim());
const menuRequest=(v:string)=>/^(menu|start|main menu|options|help menu)[!.\s]*$/i.test(v.trim());
const accommodation=(v:string)=>/\b(accommodation|student res|student residence|residence|room|rent|booking|book|secure accommodation|nsfas accommodation|tut accommodation|tvet accommodation|college accommodation|private tenant|2026 accommodation|2027 accommodation|indawo yokuhlala|madulo|bonno|bolulo|verblyf)\b/i.test(v);
const company=(v:string)=>/\b(about reskonnect|what (do|does) (you|reskonnect) do|your services|company services|services do you offer|tell me about reskonnect|who are you)\b/i.test(v);
